-- 1. Eksik sütunları ekle (Eğer yoksa)
DO $$
BEGIN
    ALTER TABLE public.reservations ADD COLUMN IF NOT EXISTS reservation_code TEXT;
    ALTER TABLE public.reservations ADD COLUMN IF NOT EXISTS status TEXT;
    ALTER TABLE public.reservations ADD COLUMN IF NOT EXISTS pickup TEXT;
    ALTER TABLE public.reservations ADD COLUMN IF NOT EXISTS dropoff TEXT;
    ALTER TABLE public.reservations ADD COLUMN IF NOT EXISTS pickup_date DATE;
    ALTER TABLE public.reservations ADD COLUMN IF NOT EXISTS pickup_time TIME;
    ALTER TABLE public.reservations ADD COLUMN IF NOT EXISTS vehicle_type TEXT;
    ALTER TABLE public.reservations ADD COLUMN IF NOT EXISTS customer_name TEXT;
    ALTER TABLE public.reservations ADD COLUMN IF NOT EXISTS customer_phone TEXT;
    ALTER TABLE public.reservations ADD COLUMN IF NOT EXISTS customer_id UUID;
    ALTER TABLE public.reservations ADD COLUMN IF NOT EXISTS customer_notes TEXT;
    ALTER TABLE public.reservations ADD COLUMN IF NOT EXISTS driver_id UUID;
    ALTER TABLE public.reservations ADD COLUMN IF NOT EXISTS driver_user_id UUID;
    ALTER TABLE public.reservations ADD COLUMN IF NOT EXISTS driver_notes TEXT;
    ALTER TABLE public.reservations ADD COLUMN IF NOT EXISTS agency_id UUID;
    ALTER TABLE public.reservations ADD COLUMN IF NOT EXISTS agency_user_id UUID;
    ALTER TABLE public.reservations ADD COLUMN IF NOT EXISTS price NUMERIC;
    ALTER TABLE public.reservations ADD COLUMN IF NOT EXISTS price_currency TEXT;
    ALTER TABLE public.reservations ADD COLUMN IF NOT EXISTS payment_type TEXT;
    ALTER TABLE public.reservations ADD COLUMN IF NOT EXISTS payment_status TEXT;
    ALTER TABLE public.reservations ADD COLUMN IF NOT EXISTS passenger_names TEXT[];
    ALTER TABLE public.reservations ADD COLUMN IF NOT EXISTS luggage_count INTEGER;
    ALTER TABLE public.reservations ADD COLUMN IF NOT EXISTS baby_seat_count INTEGER;
    ALTER TABLE public.reservations ADD COLUMN IF NOT EXISTS flight_number TEXT;
    ALTER TABLE public.reservations ADD COLUMN IF NOT EXISTS is_return_transfer BOOLEAN;
    ALTER TABLE public.reservations ADD COLUMN IF NOT EXISTS original_reservation_id UUID;
    ALTER TABLE public.reservations ADD COLUMN IF NOT EXISTS driver_earning NUMERIC;
    ALTER TABLE public.reservations ADD COLUMN IF NOT EXISTS driver_cash BOOLEAN;
    ALTER TABLE public.reservations ADD COLUMN IF NOT EXISTS driver_cash_amount NUMERIC;
    ALTER TABLE public.reservations ADD COLUMN IF NOT EXISTS driver_confirmed BOOLEAN;
    ALTER TABLE public.reservations ADD COLUMN IF NOT EXISTS pickup_lat NUMERIC;
    ALTER TABLE public.reservations ADD COLUMN IF NOT EXISTS pickup_lng NUMERIC;
    ALTER TABLE public.reservations ADD COLUMN IF NOT EXISTS pickup_place_name TEXT;
    ALTER TABLE public.reservations ADD COLUMN IF NOT EXISTS dropoff_lat NUMERIC;
    ALTER TABLE public.reservations ADD COLUMN IF NOT EXISTS dropoff_lng NUMERIC;
    ALTER TABLE public.reservations ADD COLUMN IF NOT EXISTS dropoff_place_name TEXT;
    ALTER TABLE public.reservations ADD COLUMN IF NOT EXISTS discount_amount NUMERIC;
    ALTER TABLE public.reservations ADD COLUMN IF NOT EXISTS discount_percentage NUMERIC;
    ALTER TABLE public.reservations ADD COLUMN IF NOT EXISTS promo_code TEXT;
    ALTER TABLE public.reservations ADD COLUMN IF NOT EXISTS created_at TIMESTAMPTZ DEFAULT now();
    ALTER TABLE public.reservations ADD COLUMN IF NOT EXISTS updated_at TIMESTAMPTZ DEFAULT now();
EXCEPTION
    WHEN OTHERS THEN
        RAISE NOTICE 'Sütun ekleme sırasında hata oluştu: %', SQLERRM;
END $$;

